INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'de Blob', 'de Blob is a 3D platformer where players maneuver their hero, de Blob. Equal parts amorphous blob of paint, struggling artist, revolutionary and juvenile delinquent, de Blob''s goal is to replace the drab, lifeless gray coloring that the I.N.K.T. Corporation has imposed on Chroma City and its inhabitants, the Raydians, with a range of vibrant life-giving colors, all the while avoiding and battling the gray-clad forces of the Inkies.' FROM games WHERE igdb_id = 2637 ON CONFLICT (game_id, language_code) DO NOTHING;
