INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('world-of-warcraft-wrath-of-the-lich-king-collectors-edition', 23788, '2008-11-13', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ye2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8i6i.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World of Warcraft: Wrath of the Lich King - Collector''s Edition', 'The Lich King Arthas has set in motion events that could lead to the extinction of all life on Azeroth. With the armies of the undead and the necromantic power of the plague threatening to sweep across the land, only the mightiest heroes can oppose the Lich King''s will and end his reign of terror for all time. Learn the craft of spell augmentation with the new Inscription profession. Brave the harsh new continent of Northrend, the icy domain of the Lich King. Engage in epic siege warfare, deploying mighty siege engines to lay waste to destructible buildings in your path. Transform your hero''s look with new character-customization options, including new hairstyles and dances. Explore perilous new dungeons filled with some of the deadliest creatures -- and greatest treasures. The Collector''s Edition included: The Art of World of Warcraft: Wrath of the Lich King, a 208-page book featuring never-before-seen images from the game. An exclusive in-game pet: Frosty, the baby frost wyrm. A behind-the-scenes DVD containing over an hour of developer interviews, the Wrath of the Lich King intro cinematic with director''s commentary, and more. The official soundtrack CD, containing 21 epic tracks from the game, along with exclusive bonus tracks. A mouse pad featuring a map of the newly opened continent of Northrend. Two World of Warcraft Trading Card Game March of the Legion starter decks, along with two exclusive cards available only in the Collector''s Edition.' FROM games WHERE igdb_id = 23788 ON CONFLICT (game_id, language_code) DO NOTHING;
