INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('frat-party-games-pong-toss', 85156, '2008-07-28', 20, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9kaj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kq8gjmrhsxe2rjx84oho.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frat Party Games: Pong Toss', 'The game is played using a number of small cups placed in a bowling pin fashion at both ends of the table. Each player stands behind their group of cups and tries to toss a ping pong ball into his opponent''s cups, one at a time. You can either toss the ball directly into the cup, or even bounce it off of the table. When you are successful, the ball is "removed" from the table. Your goal is to get your ball into all of your opponent''s cups before he does the same to yours.' FROM games WHERE igdb_id = 85156 ON CONFLICT (game_id, language_code) DO NOTHING;
