INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Umineko no Naku Koro ni: Episode 4 - Alliance of the Golden Witch', 'Alliance of the Golden Witch is the fourth arc in Umineko no Naku Koro ni and the final arc of the original Umineko no Naku Koro ni visual novel. It introduces the character of Ange Ushiromiya and follows her quest to discover the truth of the Rokkenjima massacre. The game was bundled with the first three episodes and was the first game to hold the full Umineko no Naku Koro ni / When They Cry 3 set of games.' FROM games WHERE igdb_id = 67170 ON CONFLICT (game_id, language_code) DO NOTHING;
