INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assassin''s Creed: Director''s Cut Edition', 'Assassin''s Creed is a non-linear action-adventure video game, during which the player controls a 12th-century Levantine Assassin named Altaïr Ibn-La''Ahad during the Third Crusade, whose life is experienced through the Animus by his 21st century descendant, Desmond Miles. The Director''s Cut Edition features four PC-exclusive memories, including the Rooftop Race Challenge, the Archer Stealth Assassination Challenge, Merchant Stand Destruction and Informant Escort Challenge.' FROM games WHERE igdb_id = 27827 ON CONFLICT (game_id, language_code) DO NOTHING;
