INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sam & Max: Beyond Time and Space', 'Join the Freelance Police for a second season of adventure, crime fighting, and chaos. Sam & Max Beyond Time and Space starts with a giant robot attack and never lets up, taking our valiant crime fighters on a gut-wrenching mission from the North Pole to Easter Island, from outer space to Hell and back. Babies will dance. Mariachis will sing. A giant battle robot will trash the streets. And when their friends are caught in the middle, Sam & Max risk their very souls to set things right.' FROM games WHERE igdb_id = 854 ON CONFLICT (game_id, language_code) DO NOTHING;
