INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chrono Trigger', 'When a newly developed teleportation device malfunctions at the Millennial Fair, young Crono must travel through time to rescue his misfortunate companion from an intricate web of past and present perils. The swashbuckling adventure that ensues soon unveils an evil force set to destroy the world, triggering Crono''s race against time to change the course of history and bring about a brighter future.' FROM games WHERE igdb_id = 20398 ON CONFLICT (game_id, language_code) DO NOTHING;
