INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Now Boarding', 'The employees of Airways Airlines are an interesting bunch. Their airport is going to be closed if they don''t get some help quick. Take charge and get the airport running smooth. Be responsible for delivering all passengers and keep them happy. But you''re not alone - employees will be working along side you. Lead your team and help them learn skills.' FROM games WHERE igdb_id = 138190 ON CONFLICT (game_id, language_code) DO NOTHING;
