INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inferno Pool', 'Inferno Pool is a mash-up of grimy, dive-bar billiards and that classic ''80s board game Crossfire. A standard eight or nine ball pool game can be played solo or with a friend, but the selling point here is a four-player extravaganza where any ball you pocket can be sent over to an opponent''s table.' FROM games WHERE igdb_id = 24332 ON CONFLICT (game_id, language_code) DO NOTHING;
