INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naruto: Clash of Ninja Revolution 2', 'NARUTO: Clash of Ninja Revolution 2 provides players with quality fighting game mechanics and a fast-paced gameplay experience on Wii. Set after Sasuke leaves the Leaf Village to gain more power from Orochimaru, the title offers a slew of playable characters, including those developed especially for the storyline. Clash of Ninja Revolution 2 features destructible stages and four-player multiplayer battles, along with gameplay modes and characters not yet seen on the Clash of Ninja series.' FROM games WHERE igdb_id = 21260 ON CONFLICT (game_id, language_code) DO NOTHING;
