INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crash: Mind Over Mutant', 'Crash: Mind Over Mutant is the sequel to Crash of the Titans and the seventh Crash Bandicoot series game. The game uses many of the same mechanics as its predecessor with a few changes. Rather than having twenty linear platforming levels to complete in sequence, Mind Over Mutant features eight distinct locations for Crash to explore and travel between as the story progresses. The player can complete missions given by non-playable characters and discover collectibles through the levels.' FROM games WHERE igdb_id = 1191 ON CONFLICT (game_id, language_code) DO NOTHING;
