INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dino Run', 'Dino Run is a 2008 game made by Pixeljam and Xgenstudios where the player navigates a dinosaur (possibly a velociraptor) through increasingly dangerous side-scrolling landscapes to escape an impending Wall of Doom. This game is made using simple pixel art and 8-bit sound to replicate the the style of 1980s arcade games.' FROM games WHERE igdb_id = 8309 ON CONFLICT (game_id, language_code) DO NOTHING;
