INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('real-soccer-2009', 20126, '2008-11-04', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7rku.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/dmjodi1g0ngxcm3e6alp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Real Soccer 2009', 'Take the field and prepare for true-to-life soccer action. Seize control of the ball and execute your most incredible moves to maneuver past your opposition and score solidly in the goal. Dazzle the spectators with your soccer prowess as you dominate the field at some of the world''s coolest stadiums. Do you have the playing skills to take your team to victory? -Exclusive Nintendo DS stylus controls allow you to easily perform the most amazing soccer moves on the Touch Screen -A multiplayer mode to face up to 3 friends in heated tournaments (Multi-Card Play) -6 different leagues and 198 teams (national and club) with real players'' names thanks to the FIFPro license -Experience the atmosphere of 12 great soccer stadiums including Milan, Manchester, and Madrid -Manage the team''s strategy using the Nintendo DS stylus in real time during the match' FROM games WHERE igdb_id = 20126 ON CONFLICT (game_id, language_code) DO NOTHING;
