INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('buzz-master-quiz', 21944, '2008-07-25', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2e6p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scspc7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buzz!: Master Quiz', 'Packing over 5,000 questions on topics including music, celebrities, TV, sport, science, nature, movies and more, Buzz! PSP puts gamer’s knowledge to the test at home or on the move. With six new round types specifically designed for PSP including the speed-is-of-the-essence ''Quickfire Challenge'', the picture-puzzler ''Picture This'' and the mind-boggling ''Virus Challenge'', each round also comes complete with pictures and videos . The focus of Buzz! has always been on social gaming and the PSP version is no different, with three exciting multiplayer modes ideal to play with friends and family. The game features three multiplayer modes that require either one PSP (to pass around) or one copy of the game (thanks to Game Share, users can pass their friends a temporary copy of the game to play to play with up to four players.) Additionally, Quiz Host mode enables up to six players to play against each other, with one taking control of the game to select and ask the questions. The Quiz Host runs the whole game, with the power to award (or even deduct) points however they see fit. Not only does Buzz! PSP offer innovative multiplayer handheld quiz action; it also has more robust single player mode than previous Buzz! games.' FROM games WHERE igdb_id = 21944 ON CONFLICT (game_id, language_code) DO NOTHING;
