INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Corpse Party', 'Corpse Party (Corpse Party BloodCovered in Japan) is a part of the Corpse Party survival horror adventure game series created by Team GrisGris for the PC. It is the remake of the original Corpse Party released in 1996 for the NEC PC-9801 with a reworked plot and new characters.' FROM games WHERE igdb_id = 11319 ON CONFLICT (game_id, language_code) DO NOTHING;
