INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Savage Moon', 'Savage Moon is a tower defense strategy game which sees the player protecting a remote, off-world mining facility from constant attack by Insectocytes, a type of carnivorous creature inhabiting the planets. The mission is to strategically place an array of upgradeable, defensive weapons in the way of the bugs. There is a range of towers, from rapid-fire machine guns to support towers such as the chaos tower.' FROM games WHERE igdb_id = 20396 ON CONFLICT (game_id, language_code) DO NOTHING;
