INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Far Cry 2', 'A civil war has swept through the country and you''re caught in the middle of it. Track down the person at the forefront of the fighting, a ruthless arms dealer known only as "The Jackal". As you undertake deadly missions and form fragile alliances with conflicting rebel groups, one thing becomes clear - the Jackal is hunting you too.' FROM games WHERE igdb_id = 361 ON CONFLICT (game_id, language_code) DO NOTHING;
