INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pokemon-ranger-shadows-of-almia--1', 14699, '2008-03-20', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1yzl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1kk8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Ranger: Shadows of Almia', 'In the second in the Pokemon Ranger series, you once again play as a Pokemon Ranger, working to help people, Pokemon and nature in a new area called the Almia Region. Starting out as a Student Ranger, you quickly earn the title of a full-fledged Pokemon Ranger. As you succeed in more and more missions, you will aspire to become the highest Ranger rank: Top Ranger. Along the way you meet and capture all kinds of different Pokemon. Capture wild Pokemon and create a team to clear obstacles and puzzles encountered along the way. After using a Pokemon’s ability, it will leave your team; however, you will have a Partner Pokemon that will always stay by your side. As you progress through Missions and Quests, your Capture Styler becomes more powerful, giving your Styler more Energy and eventually advancing you to the level of Top Ranger.' FROM games WHERE igdb_id = 14699 ON CONFLICT (game_id, language_code) DO NOTHING;
