INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('condemned-2-bloodshot', 6943, '2008-03-11', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co24nw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ifdykxcblunq8xqhbpf7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Condemned 2: Bloodshot', 'In Condemned 2: Bloodshot, players will engage in visceral combat using a variety of firearms, blunt instruments and an all-new fighting system complete with defensive and offensive combo chains, as well as grapples and holds. To help track the killer and solve the mysteries behind Condemned 2: Bloodshot, players will crack open an all-new set of high-tech forensic tools. Using wits and brute strength, murders can be solved a number of different ways to keep players guessing throughout each suspenseful investigation. Delivering the most brutal hand-to-hand combat experience the first-person genre has ever seen, Condemned 2 follows Ethan Thomas through a string of gruesome murders. Use all-new fighting mechanics and high-tech tools to unravel the mysteries within.' FROM games WHERE igdb_id = 6943 ON CONFLICT (game_id, language_code) DO NOTHING;
