INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resistance 2', 'After a valiant struggle to stop the Chimera invasion in Europe, mankind must make its last stand on the shores of the United States. Resistance 2 delivers an unprecedented console gaming experience with a standalone eight-player, class-based online co-op campaign and 60-player online competitive multiplayer. An epic single-player campaign will feature a new weapons arsenal to combat giant boss encounters that increase the scale of the conflict to new heights.' FROM games WHERE igdb_id = 3205 ON CONFLICT (game_id, language_code) DO NOTHING;
