INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('motorstorm-pacific-rift', 2554, '2008-10-28', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co26t6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/cf73fkunelhett543xxu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MotorStorm: Pacific Rift', 'The first MotorStorm wowed fans with its heady formula of brutal, unpredictable off-road racing, festival vibes and stunning Monument Valley desert scenery. Now Motorstorm Pacific Rift takes you to a solitary tropical paradise in the Pacific Ocean, ready for a whole new take on no-holds-barred racing action through thick swamps, dense jungle, towering peaks and steaming volcanoes. Not just pretty backdrops to the action, these environments take center stage in challenging players with everything in Mother Nature''s arsenal. Thick mud, tangled undergrowth, swift flowing rivers, choking volcanic clouds and searing lava pools all test the drivers to their limits and beyond. Expect a rich festival of off road racing, along with a host of game modes and rewards. It''s brutal, dangerous, relentless, and unpredictable and more than a game - MotorStorm Pacific Rift is a way of life.' FROM games WHERE igdb_id = 2554 ON CONFLICT (game_id, language_code) DO NOTHING;
