INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X3: Terran Conflict', 'It is the year 2938. The long wished-for encounter of the X Universe and the Earth holds both joy and sorrow for the people. Despite flourishing trade, the clash of the diverse races, cultures and life forms creates new tensions, mistrust and open conflict that need to be overcome! Experience the brilliant climax of the legendary X-Trilogy , and take your place in the history of the X Universe.' FROM games WHERE igdb_id = 9320 ON CONFLICT (game_id, language_code) DO NOTHING;
