INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('iridium-runners', 21504, '2008-03-19', 30, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7lc9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq1rs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Iridium Runners', 'Iridium Runners is a futuristic running game that pits competitors against each other on hazard-riddled race tracks in foot races. Players can choose one of 20 characters that have unique running skills and techniques. Some of the characters and tracks can only be unlocked as the game progresses. All of the runners will do just about anything to win, so the action can become down and dirty. Almost anything goes during the races including knocking opponents completely off the track with a well-placed kick, fist or weapon. Power-ups and booster items are scattered around the course for increasing performance, speed or providing a new method of attack. Strategy comes into play by knowing which character and which "pod" sidekick to choose. There are three modes of play: Single Race, Cup and Championship. Each offers unique environments, different obstacles and challenges. The Single Player game will put the player up against 5 CPU opponents. Multiplayer is offline and includes Deathmatch and Team modes (2 players on 2 teams) and up to 4 players in split screen.' FROM games WHERE igdb_id = 21504 ON CONFLICT (game_id, language_code) DO NOTHING;
