INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Platinum Version', 'In Pokémon Platinum, another world has emerged in the Sinnoh Region, a world where space and time are altered! Catch, train, and battle your favorite Pokémon, and discover ancient, mythical Pokémon in this exciting adventure! The platinum version also has expanded online options with new experiences in the Wi-Fi Plaza and Battle Frontier!' FROM games WHERE igdb_id = 1519 ON CONFLICT (game_id, language_code) DO NOTHING;
