INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mega-man-star-force-3-black-ace', 1786, '2008-11-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ilk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scc6tw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Star Force 3: Black Ace', 'Mega Man Star Force returns in the most thrilling series adventure yet, delivering totally upgraded and cutting-edge online communication and device customization technologies through a portable RPG adventure that is brought to life in the iconic, action-driven Mega Man way! New to the series are "Noise Changes," random enhancements that change Mega Man''s form and unlock new abilities. There are more than 100 transformations possible. Mega Man Star Force 3 will be available in two versions, Red Joker and Black Ace, each with their own unique Noise Types. Mega Man Star Force 3 blends a unique formula of RPG exploration elements with fast-paced action, as players travel and battle between coexisting worlds, the physical world and the virtual Wave World. Players will encounter enemies in the virtual Wave World and battle them on three-by-five battle grids with their Battle Card deck. Mega Man Star Force 3 also adds a new feature called "Rezon," which allow players to fill in profiles about battles and their team name/symbol.' FROM games WHERE igdb_id = 1786 ON CONFLICT (game_id, language_code) DO NOTHING;
