INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baja: Edge of Control', 'Baja: Edge of Control is an off road racing videogame developed by 2XL Games for the PlayStation 3 and Xbox 360. The game gets its name from the real life Baja 1000 off-road race, on which it is based. The game is set on over 95 different tracks, including 3 different Baja 250 courses, 2 Baja 500 courses, and 1 Baja 1000 course. The game was released September 22, 2008 in North America and September 26, 2008 in Europe.' FROM games WHERE igdb_id = 5497 ON CONFLICT (game_id, language_code) DO NOTHING;
