INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('big-beach-sports', 4712, '2008-06-24', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ptf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zsalakrbqpefnofae4be.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Beach Sports', 'All of the games allow up to 4 players playing at the same time, or in the case of Bocce and Disc Golf, taking alternate turns. All the games use the Wii Remote only, no games require the use of the Nunchuck or any other peripheral. After creating a character, the player can compete in tournaments against increasingly tougher opponents in any of the sports. Playing Quick Play games and Tournament games earns the character Skill Points. These are then used to calculate the difficulty of the CPU opponent for future Quick Play matches. Hence, after completing all tournaments for all the sports in Big Beach Sports, where each game has a preset difficulty, the player can then return to Quick Play and continue to max out Skill Points (999 points) for each of the six sports. In the case of most of the sports, however, the game becomes extremely challenging and the AI opponents are much tougher to beat after reaching 900 skill points.' FROM games WHERE igdb_id = 4712 ON CONFLICT (game_id, language_code) DO NOTHING;
