INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('george-of-the-jungle-and-the-search-for-the-secret', 4889, '2008-03-11', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dcs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ktphbypqpyqzi8l8bogx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'George of the Jungle and the Search for the Secret', 'Players take the role of George from the popular cartoon show, George of the Jungle, in a 3D side scrolling action-adventure. Players swing, climb, and platform their way through the jungle in search of the missing documents which could hold the key to the "secret" medical mystery. The camera views and turns show the 3D view, but essentially the game is played as a 2D platformer with a linear path on a single plane. Often George needs to manipulate objects in the environment, for instance moving boxes to create a platform, to continue.' FROM games WHERE igdb_id = 4889 ON CONFLICT (game_id, language_code) DO NOTHING;
