INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crash Time II', 'Solve exciting criminal cases on the mean streets as member of the autobahn police force - or freely explore the open game world while chasing down high-octane racers. Escort politicians, transport precious goods or take down the criminal element with over 500HP and close to 200MPH. With fully destructible cars, arcade gameplay, outstanding graphics and stunning slow-mo effects, Crash Time 2 puts you right in the driver seat, ready to burn rubber.' FROM games WHERE igdb_id = 6946 ON CONFLICT (game_id, language_code) DO NOTHING;
