INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ratchet & Clank Future: Quest for Booty', 'Ratchet & Clank Future: Quest for Booty (known as Ratchet & Clank: Quest for Booty in Europe, Africa and Australia) is a 2008 platform game developed by Insomniac Games and published by Sony Computer Entertainment for the PlayStation 3. The game is the sixth main instalment in the Ratchet & Clank series and the second instalment in its Future saga. The game continues from where Tools of Destruction left off, where Clank was taken by the Zoni, and follows Ratchet''s quest to find him. Due to its length of approximately three to four hours of playtime, it was released at a lower price point than most standard retail games.' FROM games WHERE igdb_id = 1794 ON CONFLICT (game_id, language_code) DO NOTHING;
