INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cross Edge', 'In a world where dreams and nightmares become reality, a band of powerful warriors from across dimensions must come together to stop their worlds from being consumed by evil incarnate. Harness the power of characters from such series as Disgaea, Ar tonelico, and DarkStalkers! Utilize the dynamic battle system to unleash powerful special skills and team combos, and choose your destiny!' FROM games WHERE igdb_id = 6948 ON CONFLICT (game_id, language_code) DO NOTHING;
