INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Suikoden Tierkreis', 'Suikoden: Tierkreis is the latest iteration of the popular RPG franchise that was introduced more than 12 years ago. Suikoden: Tierkreis follows the story of the 108 Stars of Destiny, a group of magical warriors, as they challenge the almighty One King, who intends to create chaos in the universe. As the player gathers the members of the 108 Stars of Destiny, the forces for good will stand up against evil in a battle that spans the near infinite parallel worlds of the Million World universe.' FROM games WHERE igdb_id = 1452 ON CONFLICT (game_id, language_code) DO NOTHING;
