INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('summer-athletics', 5196, '2008-07-29', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co86kf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qgitltsfnm9nqeigwtec.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summer Athletics', 'Get ready, set, go! Summer Athletics brings the action and excitement of the 26 most popular summer sporting disciplines right into your living room! The charming 3D comic style and varying levels of difficulty makes Summer Athletics great fun for the whole family. Become fully immersed in the sporting atmosphere with vibrant visual effects and awe-inspiring sporting arenas. Customize your character to make them your very own with the comprehensive customization tools within Summer Athletics. Develop your career as a professional athlete in Career Mode or challenge your friends in head-to-head competition. The intuitive controls will make Summer Athletics both a great game for beginners and a fun challenge for the more experienced player. Exciting competitions within more than 25 summer sports events Action-packed experience jammed full of amazing effects Two main game modes: Arcade & Simulation Unique career mode Four different difficulty levels Innovative & varied controls design Comprehensive customization tool for unique character design Special focus on the multiplayer experience' FROM games WHERE igdb_id = 5196 ON CONFLICT (game_id, language_code) DO NOTHING;
