INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Mummy: Tomb of the Dragon Emperor', 'The Mummy: Tomb of the Dragon Emperor is a 3D action-adventure game that was released alongside the The Mummy: Tomb of the Dragon Emperor movie. The game follows the story of the movie. You play as either Rick O''Connell or his son, Alex O''Connell and have to thwart the plans of the Dragon emperor and his Terracotta army.' FROM games WHERE igdb_id = 5023 ON CONFLICT (game_id, language_code) DO NOTHING;
