INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pro-evolution-soccer-2009', 4648, '2008-10-17', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5vzo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsoxj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Evolution Soccer 2009', 'Pro Evolution Soccer 2009 (often shortened to PES 2009, or simply PES 09) is an association football video game in Konami''s Pro Evolution Soccer series. It is the sequel to Pro Evolution Soccer 2008. Before the game was released, it was revealed that creator Shingo Takatsuka had given the game a complete overhaul following the serious criticism of the previous title. The game supports network play with a reduction in lag compared to PES 2008. Lionel Messi is featured as the cover star, although Andrés Guardado features on some versions. A new game mode called Become a Legend was introduced, which involves creating a player and taking him through a career. The Master League mode saw the introduction of two-tier negotiations, which involve negotiating with the club first and then the player separately. The Edit Mode was also improved. The game was followed by PES 2010.' FROM games WHERE igdb_id = 4648 ON CONFLICT (game_id, language_code) DO NOTHING;
