INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blast-works-build-trade-destroy', 4720, '2008-06-10', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2hqb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/y9fyawci8mj7ae1rrsev.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blast Works: Build, Trade, Destroy', 'Blast Works: Build, Trade, Destroy challenges shooter fans to a frenetic geometric battle exclusively for Nintendo Wii. As you destroy enemies, you’ll catch their parts and use them to make your own ship bigger and stronger. Then, unleash your creativity with the easy-to-use Blast Works editor where you can create your own ships, enemies and levels. Finally, trade these creations directly with friends or share with the entire Blast Works community at BlastWorksDepot.com. With bright, abstract graphics and fast-paced, dynamic action, this “sticky” shooter based on Kento Cho’s Tumiki Fighters online game will suck you in for the long haul.' FROM games WHERE igdb_id = 4720 ON CONFLICT (game_id, language_code) DO NOTHING;
