INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mortal-kombat-vs-dc-universe', 1617, '2008-11-16', 77, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y13.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fd59auikrhtz540fdhwx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mortal Kombat vs. DC Universe', 'In this arcade-style fighting game, both DC and Mortal Kombat universes are represented by 10 champions each, and one "boss" character, for a total of 22 fighters. Play is similar to the 2D Mortal Kombat games (with some 3D elements), focusing more on the special move aspect than the complex combos found in the previous three games (Deadly Alliance, Deception, Armageddon). As with any Mortal Kombat game, Fatalities are still present for the Kombatants and villains, though slightly toned down to meet the DC standards of heroes such as Superman and Batman keeping to their moral code and not killing their opponent. As a result, the DC heroes perform "Heroic Brutalities", which effectively put their opponent out of commission.' FROM games WHERE igdb_id = 1617 ON CONFLICT (game_id, language_code) DO NOTHING;
