INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! GX Tag Force 3', 'TAG FORCE is back in the hot third installment featuring cards up to the Crossroads of Chaos Set. Battle against Jaden and his pals including Haou Jaden and Mr. T (Truman), Jessie, Bastion, and even Yubel! Fully animation dueling is a must as well as the return of the Seasonal events and Mail System from the 1st Tag Force Game. TAG FORCE 3 takes you into the world of Duel Academy like never before, and is trip you don''t want to miss.' FROM games WHERE igdb_id = 44494 ON CONFLICT (game_id, language_code) DO NOTHING;
