INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpongeBob SquarePants: Fists of Foam', 'Fists of Foam is an educational video game that was released in 2008 for the LeapFrog Didj and later for LeapFrog Leapster Explorer in 2012. In this game, Master Udon has captured Sandy and it''s up to SpongeBob and Patrick to save her. This game is based on the episode "Karate Island."' FROM games WHERE igdb_id = 230401 ON CONFLICT (game_id, language_code) DO NOTHING;
