INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynasty Warriors: Gundam 2', 'Dynasty Warriors: Gundam 2 combines the devastating power of the mobile suit, the rich legacy of the anime Gundam universe, and the furious tactical action gameplay of the Dynasty Warriors series. For the first time, engage in melee battles against colossal enemies such as the Psycho Gundam who can quickly reconfigure their bodies into titanic mobile fortresses. Prepare to head off into the furthest reaches of space and wage war against legions of enemy mobile suits.' FROM games WHERE igdb_id = 6978 ON CONFLICT (game_id, language_code) DO NOTHING;
