INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pure', 'Developed by Black Rock Studio, Disney Interactive Studios'' award-winning development studio in Brighton, England, Pure takes off-road racing to a new level. Featuring vertigo-inducing massive aerial jumps and spectacular airborne tricks in photo-realistic real-world locations all over the globe, Pure delivers heart-pounding experiences unique to the genre.' FROM games WHERE igdb_id = 7137 ON CONFLICT (game_id, language_code) DO NOTHING;
