INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('viva-pinata-trouble-in-paradise', 7238, '2008-09-02', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2z8o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8jp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Viva Piñata: Trouble in Paradise', 'The original Rare Ltd. team behind Viva Piñata has reunited to bring gamers Viva Piñata: Trouble in Paradise, the newest and most fun piñata adventure to date. Available exclusively on Xbox 360, Viva Piñata: Trouble in Paradise reinvigorates a colorful and engaging gaming experience on the Xbox 360 platform. Now with full cooperative and online gameplay modes, the Viva Piñata franchise opens its doors even wider with a new game that provides hours of fun for gamers of all ages, fans of the animated series and animal lovers alike. Return to magical Piñata Island. Unfortunately, not all is well on the island, as Professor Pester and his gang of Ruffians have wiped out Piñata Central''s computer records, posing a threat to parties everywhere. Rebuild the computer database and thwart Professor Pester''s evil plot by sending piñatas at full candiosity to parties all around the world. Build and maintain your piñata gardens—using your creativity and imagination to attract, trap, protect, train, and manage more than 100 different piñata species.' FROM games WHERE igdb_id = 7238 ON CONFLICT (game_id, language_code) DO NOTHING;
