INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You''re in the Movies', 'You''re in the Movies is a party game and features the process of filming a movie on one of the 30 scenarios that can involve up to four people. Actions include the application of make-up, jogging in place, driving a car and playing volleyball. Previous video can be stored on the console, as well as to send to friends via e-mail.' FROM games WHERE igdb_id = 7258 ON CONFLICT (game_id, language_code) DO NOTHING;
