INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Pokémon Ranch', 'The Pokémon phenomenon debuts on WiiWare with My Pokémon Ranch, a game that lets you watch as Pokémon and Miis interact with each other for the first time. Enjoy the relaxing ranch life by viewing your ranch and its Pokémon, taking pictures and sending those pictures to your friends via the Wii Message Board. The more Pokémon and Miis you bring to your ranch, the more fun it becomes.' FROM games WHERE igdb_id = 4563 ON CONFLICT (game_id, language_code) DO NOTHING;
