INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AdventureQuest Worlds', 'Updated every Friday with new stories, items, quests, monsters and more! Join thousands online and defend the world from Drakath and his 13 Chaos Lords. Team with your friends and take on challenging bosses to get rare rewards! With a storyline that updates weekly, our very first MMO always has something new for you to do, epic loot to collect, and other heroes to battle with... or against!' FROM games WHERE igdb_id = 107272 ON CONFLICT (game_id, language_code) DO NOTHING;
