INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Afrika', 'Become a photo journalist in the wild yonder of Africa in a videogame featuring amazing, realistic animal models and vast landscapes to visit. Africa''s animals and plants are all rendered in stunning photorealistic detail. As a photographer, you''ll use licensed, real-world photography equipment to complete assignments and capture everything from bathing hippos to a cheetah on the hunt. Explore the land, find new animals, and earn a name for yourself as a professional photographer!' FROM games WHERE igdb_id = 7267 ON CONFLICT (game_id, language_code) DO NOTHING;
