INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Luminous Arc 2', 'More Strategy, More Witches, More Fun! As the threat of a rogue Witch looms over Carnava, the Queen calls upon the Magic Association to save the land. Beautiful hand drawn graphics and a stunning score from Yasunori Mitsuda''s Procyon Studio combine with multiplayer support to create the must-have strategy RPG of the year! "Engagement" System - Gain potent Witch powers with this intriguing new tactical feature. Refined Mechanics - Upgraded interface, polished touch controls, and rebalanced gameplay.' FROM games WHERE igdb_id = 21330 ON CONFLICT (game_id, language_code) DO NOTHING;
