INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('euro-truck-simulator', 6653, '2008-08-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa08n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arpuw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Euro Truck Simulator', 'The original Euro Truck Simulator - the game which has become the classic of the genre and is still relevant today. The first truck simulation game in a European setting, with European long haul trucks! Drive freight from London to Rome to Berlin to Madrid to Prague - and many more cities - in realistic vehicles. Faithful reproduction of driving trucks on the European road. Pick up a variety of cargoes, and deliver them on time! Highly realistic, meticulously detailed models based on real trucks. Actual working instruments such as flashing indicators, temperature and low fuel warning lights, wipers, and a full set of gauges. Pan the camera around the cabin, just as if you were actually sitting at the wheel.' FROM games WHERE igdb_id = 6653 ON CONFLICT (game_id, language_code) DO NOTHING;
