INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Unleashed', 'Gameplay in Sonic Unleashed focuses on two modes of platforming play: fast-paced levels that take place during daytime, showcasing Sonic''s trademark speed as seen in previous games in the series, and slower, night-time levels, during which Sonic''s Werehog form emerges, and gameplay switches to an action-based, brawler style of play, in which Sonic battles Gaia enemies' FROM games WHERE igdb_id = 5169 ON CONFLICT (game_id, language_code) DO NOTHING;
