INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saints Row 2', 'After the events of the first game, you awaken from a coma to find that the Third Street Saints have all but disappeared. Much like Saints Row, you are charged with retaking the city from three rival gangs, only this time as the leader of the saints. While fighting the Sons of Samedi, The Brotherhood, and The Ronin, the Saints also antagonize the Ultor Corporation, which seeks to eradicate gang violence in Stilwater once and for all.' FROM games WHERE igdb_id = 826 ON CONFLICT (game_id, language_code) DO NOTHING;
