INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Valkyrie Profile: Covenant of the Plume', 'The origins of a cult classic are revealed in VALKYRIE PROFILE: Covenant of the Plume, the third entry in the critically acclaimed VALKYRIE PROFILE series. Development studio tri-Ace returns to craft a gameplay experience that boasts a captivating storyline with ties to Norse mythology and a familiar yet refreshing battle system enhanced with deeper strategic elements.' FROM games WHERE igdb_id = 6579 ON CONFLICT (game_id, language_code) DO NOTHING;
