INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dr-mario-express', 47847, '2008-12-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4lat.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ptwianbq1wyvzirshyls.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr. Mario Express', 'Dr. Mario Express, known in Japan and PAL regions as A Little Bit of... Dr. Mario (ちょっとDr. MARIO Chotto Dr. Mario?),[5] is a Mario action puzzle video game published by Nintendo. The game was released exclusively as a DSiWare title for the Nintendo DSi platform. Dr. Mario Express was first released as a launch title for the DSiWare service in Japan on December 24, 2008, and was released in both North America and PAL regions in 2009. The game was developed by Arika, which had also created Dr. Mario Online Rx for WiiWare. Dr. Mario Express features the general gameplay of earlier Dr. Mario puzzle games, which focus on eliminating colored viruses from the playing field by matching them with colored capsules. Dr. Mario Express received generally positive reviews, but was criticized for offering fewer playable game modes than earlier Dr. Mario titles.' FROM games WHERE igdb_id = 47847 ON CONFLICT (game_id, language_code) DO NOTHING;
