INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('guitar-hero-world-tour', 2669, '2008-10-26', 83, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wng.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4lx3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guitar Hero World Tour', 'Guitar Hero: World Tour is the fourth main game in the series and brings a major change to the concept. Following the release of Rock Band that built on the Guitar Hero concept but added additional instruments, World Tour introduces these as well to allow players to play together simultaneously as a real band. Next to the guitar that was the main peripheral for the previous titles, the bundled edition of the game adds a microphone for the vocal parts and drums for percussion. Just like the previous game, the guitar tracks are split up for the lead and bass. The lyrics and the vocal pitch is shown near the top of the screen, while the bottom part is split up for bass guitar, lead guitar and drums, each with a separate set of notes that need to be hit to correctly play the part.' FROM games WHERE igdb_id = 2669 ON CONFLICT (game_id, language_code) DO NOTHING;
