INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Banjo-Kazooie', 'The Xbox 360 remaster of Banjo-Kazooie has visual and performance improvements over the Nintendo 64 version. In this version, the player doesn''t lose the notes after getting out of a stage, which is a major difference over the original, since it doesn''t require the player to get everything again after leaving or dying.' FROM games WHERE igdb_id = 201644 ON CONFLICT (game_id, language_code) DO NOTHING;
