INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('locoroco-2', 1461, '2008-11-21', 93, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ja3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4k1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LocoRoco 2', 'The LocoRoco are in danger again, the evil Moja have returned and this time they''ve brought with them a terrible song that sucks the life out of living things! The LocoRoco must once again save their planet - this time by making lots of sweet music. LocoRoco 2 is easy to play, instantly addictive and guaranteed to make you feel all warm and fuzzy while you hum along to the soundtrack! Explore 25 new stages, including hidden challenges, and meet a colourful cast of new characters. Enhance your LocoRoco through music and song, learning new actions to overcome the Moja. Perform new actions such as climbing inside shells to destroy thorns, jumping from grass blade to grass blade and swimming underwater. Expand your fun with six new mini games, including an Ad-hoc four player game.' FROM games WHERE igdb_id = 1461 ON CONFLICT (game_id, language_code) DO NOTHING;
