INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Omega Five', 'The baddest guys around have been gathered together in order to save the beautiful planet from the clutches of invaders! Take control of characters such as a pirate, alien, or samurai and unleash aggressive action against the invading mechanical life forms using the most awesome weapons in the galaxy! Team up with another player in multiplayer for co-op action or go solo in single player and shoot for the high score with Omega Five''s intense scoring system!' FROM games WHERE igdb_id = 21811 ON CONFLICT (game_id, language_code) DO NOTHING;
