INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Sector', 'Dark Sector thrusts players into the role of Hayden Tenno, a covert operative sent on a dangerous mission into Lasria, an Eastern European city on the brink of ruin that hides a deadly Cold War secret. In the midst of this mission, Hayden is attacked by an unknown enemy and infected by the Technocyte Virus, a brutal bio-weapon that twists its victims into mindless killing machines. Surviving this attack, Hayden finds that the Technocyte virus has granted him powerful, inhuman abilities unlike anything he has ever seen. Now, he must evolve with his powers, survive and become a hero.' FROM games WHERE igdb_id = 6959 ON CONFLICT (game_id, language_code) DO NOTHING;
