INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA 2K9', 'Improved facial and skin textures, better uniforms, improved eye movement and more realistic crowd reactions bring the game alive like never before. Analyst Clark Kellogg and sideline reporter Cheryl Miller join color commentator Kevin Harlan to create one of the most knowledgeable broadcast teams in the game. End each quarter with enhanced, multiple angle replay highlights, and be rewarded like never before with all-new, true-to-life celebration sequences after you capture the NBA championship.' FROM games WHERE igdb_id = 8838 ON CONFLICT (game_id, language_code) DO NOTHING;
