INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World of Goo', 'World of Goo is a multiple award winning physics based puzzle / construction game made entirely by two guys. Drag and drop living, squirming, talking, globs of goo to build structures, bridges, cannonballs, zeppelins, and giant tongues. The millions of Goo Balls that live in the beautiful World of Goo are curious to explore - but they don''t know that they are in a game, or that they are extremely delicious. Congratulations, and good luck!' FROM games WHERE igdb_id = 942 ON CONFLICT (game_id, language_code) DO NOTHING;
