INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ninjatown', 2825, '2008-10-28', 74, 'https://images.igdb.com/igdb/image/upload/t_cover_big/t3ipg9d7fin95v0f5ob9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bcwrs2gztqlg2qcrqbum.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninjatown', 'A diverse group of fun-loving Ninjas populate the vibrant yet peaceful place known as Ninjatown. However, after the eruption of a nearby volcano, Ninjatown is attacked by hordes of sinister enemies lead by Mr. Demon, who, for reasons unknown, is bent on destruction. It is now time to use each of the Ninjas'' unique skills and powers - including the Mighty Wind of Ninja Dropping and Stealth Hugs - to fight off the evil and secure Ninjatown, one district at a time. The game is played from the top down, where the player uses the stylus to strategically place Ninjas to defend each area.' FROM games WHERE igdb_id = 2825 ON CONFLICT (game_id, language_code) DO NOTHING;
