INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Slug 7', 'The Peregrine Falcon Strike Force, the Ikari Warriors, and the SPARROWS are once again on a search for General Morden and his army. Their mission is to catch General Morden and prevent his attempts at another coup d''état on the government. However, as soon as Morden was defeated, a strange army from the future came to his aid. Now, they must face Morden once again and this time, put a stop to his plans once and for all.' FROM games WHERE igdb_id = 1412 ON CONFLICT (game_id, language_code) DO NOTHING;
