INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Shodown: Edge of Destiny', 'Samurai Shodown: Edge of Destiny follows a young European girl named Suzu, rescued from a sinking ship off Japan''s coast, adopted by the Amori Clan and raised as Princess Suzu. A decade later she saves Takechiyo, a self-proclaimed master of martial arts, after his ship sinks and he ends up washed on the beach; soon after this chance meeting, the tables turn when Princess Suzu mysteriously disappears and Takechiyo pledges to find his missing rescuer.' FROM games WHERE igdb_id = 7172 ON CONFLICT (game_id, language_code) DO NOTHING;
