INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery Case Files: MillionHeir', 'Mystery Case Files: MillionHeir is a puzzle adventure video game developed by Big Fish Games and Griptonite Games and published by Nintendo,[1] for the Nintendo DS handheld video game console. It was first released in North America, was later released in Australia, and then Europe. It is the second Mystery Case Files game to be made for a portable device. Although the game is part of the Mystery Case Files brand, it is not a part of the main computer game series.' FROM games WHERE igdb_id = 20276 ON CONFLICT (game_id, language_code) DO NOTHING;
