INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nanashi no Game', 'Nanashi no Game is a first-person survival horror video game developed by Epics and published by Square Enix for the Nintendo DS. The game follows a university student who becomes cursed by the titular role-playing game, which causes people to die in seven days upon starting.' FROM games WHERE igdb_id = 67979 ON CONFLICT (game_id, language_code) DO NOTHING;
