INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aces of the Galaxy', '3, 2, 1 Blast-Off! Launch yourself into the intense space-shooter Aces of the Galaxy  A non-stop, old-school arcade thrill-ride for the 21st century and beyond. Utilize an impressive arsenal of upgradeable weapons including high powered missile launchers, devastating torpedoes and the ever-reliant chain gun to annihilate the ships of the wretched Skurgian Empire.' FROM games WHERE igdb_id = 15766 ON CONFLICT (game_id, language_code) DO NOTHING;
