INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prey the Stars', 'In Prey the Stars – known as Gabu Gabu Planet in Japan – players control various dog-like creatures in a competition to eat the most items in a given level. Part of the challenge comes in that, in order to successfully eat an item, you must "chew" it by repeatedly pressing the B button.' FROM games WHERE igdb_id = 21337 ON CONFLICT (game_id, language_code) DO NOTHING;
