INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('eco-creatures-save-the-forest', 21280, '2008-04-04', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/m3jqwshkdyarg0sf5iaz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/s2qukz0pdkvscddqpcyc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eco-Creatures: Save the Forest', 'Deforestation, pollution, global warming and industrialization are just some of the many important themes in Eco Creatures: Save the Forest, a unique real-time strategy game and the only game of its kind that promotes awareness of environmental perils while tasking players with defending the Mana Woods against them. Players use the Touch Screen to control units of woodland creatures—named Ecolis, Ecoby and Ecomon—that will protect the naturally beautiful Mana Woods and recover the polluted land. All creature types have unique skills that must be strategically managed. With proper nurturing, they can evolve to learn new abilities that help a player complete the game’s more than 40 environmental missions. As players grow their woodland army, they must also plant new trees to prevent deforestation and revitalize the woodlands. In addition, Eco Creatures includes a creative Land Make feature that lets players build and play their own maps. This eco-friendly RTS also supports two-player play via Nintendo Wi-Fi Connection, and up to four players via single card download play or ad-hoc multi-card play.' FROM games WHERE igdb_id = 21280 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 21280 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
