INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rock Revolution', 'Rock Revolution lets you release your inner rockstar or allows your friends the privilege of picking up an axe or pounding the skins with you to 41 mind bending rock tracks! Unleash your creative juices in the Studio Mode where you can create your own music in a state of the art multi-track studio! This is the musical revolution the world has been waiting for!' FROM games WHERE igdb_id = 7164 ON CONFLICT (game_id, language_code) DO NOTHING;
