INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brainpipe: A Plunge to Unhumanity', 'BRAINPIPE is a unique gaming experience. The ultimate objective is to transcend humanity. You do this by navigating the tunnels of your mind, exercising your hand-eye coordination while relishing in the funkadelic sights and sounds of your inner self. Collect the illuminated glyphs while avoiding the nasty obstacles. They may look all nice and shiny, even warm and inviting, but each brush with them brings you one step closer to eternal darkness!' FROM games WHERE igdb_id = 29203 ON CONFLICT (game_id, language_code) DO NOTHING;
