INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mirror''s Edge', 'In a city where information is heavily monitored, couriers called Runners transport sensitive data. In this seemingly utopian paradise, a crime has been committed, and you are being hunted. You are a Runner called Faith and this innovative first-person action-adventure is your story.' FROM games WHERE igdb_id = 1051 ON CONFLICT (game_id, language_code) DO NOTHING;
