INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Etrian Odyssey II: Heroes of Lagaard', 'In the Grand Duchy of High Lagaard, it is said that the Duke is descended from inhabitants of a castle in the sky. When an unforeseen crisis befalls the nation, it is decreed that the first explorer to retrieve the Grail of Kings from that mythical floating palace will be rewarded with wealth and fame beyond imagining. Enter the central city of Lagaard and begin your journey to the clouds!' FROM games WHERE igdb_id = 14717 ON CONFLICT (game_id, language_code) DO NOTHING;
