INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lost Crown', 'Unravel an ancient mystery and search for an ancient treasure on England''s fog-shrouded coastline, famed for its legends of smugglers, pirates and ghosts. Join ghost-hunters Nigel Danvers and Lucy Reubans as they investigate a tale of horror and haunting. Wielding the tools of the modern-day ghost-hunter in a cinematic, richly detailed interactive world of wind-swept coastlines and crumbling crypts, you will be captivated, taunted and teased by mind-bending puzzles and interactions with the town ''locals''. But, be warned, there are those who will stop at nothing to prevent Nigel discovering "that which should stay hidden". With nerves of steel and wits to match, in your search for The Lost Crown you will soon discover long lost secrets previously known only to the dead!' FROM games WHERE igdb_id = 11621 ON CONFLICT (game_id, language_code) DO NOTHING;
