INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hellboy: The Science of Evil', 'Experience the epic adventures of the acclaimed comic book hero, fusing action, atmosphere, and humor in Hellboy: The Science of Evil. In his latest quest, Hellboy uncovers an insane Nazi plot for world domination, and must rush to defeat the crazed Hermann Von Klempt before he can exert his evil will upon earth. Unleash Hellboys superhuman abilities as you smash your way through hordes of enemies using the environment for added destructive power and strategy. Just another day for Hellboy ...' FROM games WHERE igdb_id = 7007 ON CONFLICT (game_id, language_code) DO NOTHING;
