INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Driller Online', 'Players take on the role of a driller moving through levels of colorful blocks, avoiding the threat of being crushed by falling blocks, all while keeping their air supply from running out. Mr. Driller Online features single player modes including Standard Driller and Quest Driller, as well as online multiplayer support for up to four players on Xbox LIVE. In online multiplayer mode, players can participate in a split screen Solo Battle, where the best score wins, or in Tag Battle, where friends team up in pairs to beat the game.' FROM games WHERE igdb_id = 21356 ON CONFLICT (game_id, language_code) DO NOTHING;
