INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drakensang: The Dark Eye', 'Drakensang is a third-person party-based RPG based on the pen & paper role-play rules of The Dark Eye. Drakensang is the first PC game for over 10 years to be based on Germany''s most successful and popular role-play system. Drakensang builds on the pen & paper rules as applied in version 4.0. The developers have optimized the rulebook specially for the PC realization in order to make the game more accessible. But the essential qualities and the depth of the original rules have not been compromised.' FROM games WHERE igdb_id = 8768 ON CONFLICT (game_id, language_code) DO NOTHING;
