INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Top Spin 3', 'Top Spin 3 includes more than 25 of the world''s top tennis superstars including Roger Federer, Andy Roddick, Maria Sharapova, James Blake, and many others. With all-new action-packed features including signature player animations and expressions, weather changes, situation-specific behaviors, along with revamped audio with enhanced crowd reaction, Top Spin 3 serves up a realistic and exciting tennis video game experience.' FROM games WHERE igdb_id = 5232 ON CONFLICT (game_id, language_code) DO NOTHING;
