INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gradius ReBirth', 'Blast your way through levels filled with alien spaceships and otherworldly creatures in this retro side-scrolling shooter. Pick your weapons carefully and upgrade them to create a devastating arsenal of space-aged weapons that will aid you in your challenging mission. Players can post their high scores to worldwide leader boards via Nintendo Wi-Fi Connection and see where they rank against all the other Gradius ReBirth players. Test your skills with Gradius ReBirth and see if you have what it takes to beat this action-packed arcade shooter.' FROM games WHERE igdb_id = 1489 ON CONFLICT (game_id, language_code) DO NOTHING;
