INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Race Driver: Grid', 'Discover a stunning world of motor sport brought to life, from racing muscle cars through the iconic streets of San Francisco and competing in the legendary 24 hours of Le Mans to drifting around the docks of Yokohama. Jump behind the wheel of exhilarating racing cars in the most aggressive, spectacular wheel-to-wheel races you''ve ever experienced.' FROM games WHERE igdb_id = 2159 ON CONFLICT (game_id, language_code) DO NOTHING;
