INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: The Clone Wars - Lightsaber Duels', 'Star Wars: The Clone Wars - Lightsaber Duels allows players on the Wii to step right into the world of the all-new Star Wars: Clone Wars animated feature film and television series, ready for action with a lightsaber at their side. Set in context between Star Wars movies, Episode II: Attack of the Clones and Episode III: Revenge of the Sith, it unveils a whole new and interactive chapter in the Star Wars saga.' FROM games WHERE igdb_id = 5194 ON CONFLICT (game_id, language_code) DO NOTHING;
