INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: The Force Unleashed', 'Star Wars: The Force Unleashed is a Star Wars video game that takes place between the films Star Wars: Episode III Revenge of the Sith and Star Wars: Episode IV A New Hope. It is the centerpiece of the Star Wars: The Force Unleashed multimedia project, Star Wars: The Force Unleashed completely re-imagines the scope and scale of the Force and casts players as Darth Vader’s "Secret Apprentice," unveiling new revelations about the Star Wars galaxy seen through the eyes of a mysterious new character armed with unprecedented powers. The game showcases Digital Molecular Matter (DMM), an extremely detailed and realistic material physics engine developed by Pixelux, and Euphoria, a realistic bio-mechanical A.I. engine by NaturalMotion' FROM games WHERE igdb_id = 475 ON CONFLICT (game_id, language_code) DO NOTHING;
