INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nerf N-Strike', 'Become the master of mayhem in the first NERF blaster action game. In a world created to be the perfect landscape for NERF pandemonium, players can wreak havoc and perfect their blasting skills or challenge friends to clashes with both single and multi-player game modes. With the brand new custom NERF blaster, players can then take the action outside as their controller transforms to fire actual NERF darts.' FROM games WHERE igdb_id = 2665 ON CONFLICT (game_id, language_code) DO NOTHING;
