INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Audiosurf', 'Audiosurf is a puzzle/rhythm hybrid game created by Invisible Handlebar, a personal company created by Dylan Fitterer. It''s track-like stages visually mimic the music the player chooses, while the player races across several lanes collecting colored blocks that appear in sync with the music. The music used in the game is chosen from the user''s own library, from almost any DRM-free format, as well as standard redbook CDs; in addition, Audiosurf includes the entire soundtrack to The Orange Box as part of the download.' FROM games WHERE igdb_id = 2956 ON CONFLICT (game_id, language_code) DO NOTHING;
