INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fieldrunners', 'Descend into the world of Fieldrunners, the most anticipated and visually stunning game in tower defense history! Defend and control the field using a diverse selection of upgradeable towers in a limitless adventure, using a wide array of tactics and strategies against countless waves of unique land and air combatants! Hours of entertainment and replayable challenges! Do you have what it takes to dominate the Fieldrunners and rise to the top as the ultimate Tower Defense master? Find out now!' FROM games WHERE igdb_id = 9839 ON CONFLICT (game_id, language_code) DO NOTHING;
