INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grimm', 'Experience an incredible adventure built around the world''s best-known fairy tales. As Grimm, you will transform the classic tales of Little Red Riding Hood, Cinderella, Jack and the Beanstalk, and more of your favorites into darkly twisted Grimm versions of themselves in 23 episodes. Each game episode is centered around one of the world''s best-known fairy tales and provides 30 minutes of gameplay. Each episode is a complete, standalone experience and the episodes can be played in any order.' FROM games WHERE igdb_id = 16678 ON CONFLICT (game_id, language_code) DO NOTHING;
