INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('xenus-2-white-gold', 30872, '2008-10-08', 59, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3l96.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/areyx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xenus 2: White Gold', 'Caribbean islands; islands full of secrets, mystery and the spirit of romance. These islands are both beautiful and lethally dangerous. Centuries ago the waters of this region were teeming with pirates and adventurers... and frankly, not much has changed since then. Many books have been written about the Caribbean basin and many films have depicted it. Now you have a unique chance to visit these places yourself and personally witness the everyday life of drug-dealers, bandits and the Mafioso. You''ll be able to take part in various mysterious events and get involved in fights between various hostile forces, or just admire the luscious tropical environment while drinking the traditional pirate''s liquor - rum. The Caribs are waiting for you!' FROM games WHERE igdb_id = 30872 ON CONFLICT (game_id, language_code) DO NOTHING;
