INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider-Man: Web of Shadows', 'Spider-Man: Web of Shadows is a video game title encompassing three versions: a full-3D action game for Microsoft Windows, PlayStation 3, Wii, and Xbox 360; a 2.5D sidescrolling beat em up action game for the PlayStation Portable and PlayStation 2 (called Amazing Allies Edition), and a 2.5D side-scrolling brawler/platformer for the Nintendo DS. Spider-Man: Web of Shadows, along with most other games published by Activision that had used the Marvel licence, was de-listed and removed from all digital storefronts on January 1, 2014.' FROM games WHERE igdb_id = 5181 ON CONFLICT (game_id, language_code) DO NOTHING;
