INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Rainbow Six 3: Gold Edition', 'Raven Shield: Command an elite multinational squad of special operatives against hidden terrorist forces. In Tom Clancy''s Rainbow Six 3: Raven Shield, the third installment to the wildly popular Rainbow Six series, Team Rainbow faces the hidden global forces of a new and secretive foe. Rainbow Six 3 Gold Download Features: - All-new eight-mission campaign in locations from Italy and Croatia to Greece. - Five new multiplayer levels (Chemical Factory, Ferry Boat, University, Italian Alleys, and Jungle). - Three new multiplayer game modes (Adversarial Terrorist Hunt, Adversarial Scattered Hunt, and Capture the Enemy). - Seven additional real-world weapons (for a total of 64) with sound effects from the team that worked on the blockbuster movie The Matrix.' FROM games WHERE igdb_id = 28989 ON CONFLICT (game_id, language_code) DO NOTHING;
