INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('auditorium', 15282, '2008-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co248e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/e5cy2zg52ocbhbfxiwaj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Auditorium', 'In Auditorium, the player uses various game mechanics to bend streams of light particles to fill audio containers. As each of the audio containers is filled, an audio channel introducing an instrument or sound is added to the game''s music. In most levels, the audio containers are a variety of colors which the particle stream must match in order to fill it. The player changes the color of the stream by manipulating it over fixed areas of the level which dye the particles as they pass through them. The goal of each level is to direct and split the stream in such a way that each audio container is filled simultaneously, revealing the level''s full soundtrack.' FROM games WHERE igdb_id = 15282 ON CONFLICT (game_id, language_code) DO NOTHING;
