INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maboshi''s Arcade', 'The game features three minigames, Circle, Bar and Square, each played differently but with the same objective (scoring one million points) and played on the same screen. Each game can either be played separately or with two or all three simultaneously played by multiple players, with gameplay in one game interacting with and affecting the other games.' FROM games WHERE igdb_id = 21788 ON CONFLICT (game_id, language_code) DO NOTHING;
