INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Homie Rollerz', 'Homie Rollerz is a fast-paced, mayhem-laden kart racer where players can pick one of the 10 most popular Homies, customize their slick rides, then trick, hop, and battle through courses with settings, shortcuts, and secrets as unique as the Homies themselves.' FROM games WHERE igdb_id = 21493 ON CONFLICT (game_id, language_code) DO NOTHING;
