INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Around the World in 80 Days', 'Visit four continents in this match 3 puzzle game inspired by the classic adventure written by Jules Verne. Travel back in time to the late 19th century and get ready for adventures on land, sea and in the air. Join English daredevil Phileas Fogg and his loyal French servant, Passepourtout, on this journey.' FROM games WHERE igdb_id = 80445 ON CONFLICT (game_id, language_code) DO NOTHING;
