INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloons TD 3', 'It''s here. After 319 days, 32 Million plays and countless requests for a sequel to Bloons Tower Defense 2, Ninja Kiwi is proud to present Bloons Tower Defense 3. This time, use the all new towers and upgrades to work your way through 8 all new tracks and 3 difficulty modes to achieve that total Bloon popping satisfaction.' FROM games WHERE igdb_id = 109113 ON CONFLICT (game_id, language_code) DO NOTHING;
