INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mata Hari', 'TRUST NO ONE BUT YOURSELF as you adventure into the dark world of espionage amidst the volatile atmosphere of impending war. As a double agent, you must find clever ways to pit enemy factions against each other while eluding pursuers in each of your increasingly dangerous missions. As a femme fatale, your notorious charm can entice any man. Yet, will the one man who holds the key to your heart ever be yours?' FROM games WHERE igdb_id = 27853 ON CONFLICT (game_id, language_code) DO NOTHING;
