INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DropCast', 'Ingrid did not play nice with the other boys and girls so she decided to make some new friends…from her stuffed animals. Once her toys came to life they needed life skills, and she was happy to teach them 24 devastating spells to use and abuse.' FROM games WHERE igdb_id = 21458 ON CONFLICT (game_id, language_code) DO NOTHING;
