INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SAS Secure Tomorrow', 'A perfectly organized terrorist group has rescued their leader from a high security prison. Now, SAS steps in. At the time, nobody expected the situation would get so much out of hand. Join the elite military formation and support them in the fight against terrorism. Perfect training and cutting-edge equipment give you advantage over any enemy.' FROM games WHERE igdb_id = 10811 ON CONFLICT (game_id, language_code) DO NOTHING;
