INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boogie Superstar', 'Boogie SuperStar, the sequel to Boogie, is a dancing and karaoke game. It can be played with either the included microphone for singing or with the wii remote for dancing. Players need to match the rhythm and pitch to sing, or follow a specific dance routine by performing sequences of dance moves and combos to dance. The objective of the game is to work your way to stardom by competing in the star show where you can earn tokens that can be redeemed for reward packages. These contain new songs, dance moves, combos, dance routines, dressing room items as well as style skill progression.' FROM games WHERE igdb_id = 4726 ON CONFLICT (game_id, language_code) DO NOTHING;
