INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Baron Arcade', 'Engage in the ultimate World War I arcade flight-shooter Red Baron Arcade. Grab the flight stick of 20 historic WWI planes and battle countless enemies including huge zeppelins, powerful battleships and authentic WWI aircraft in over 36 varied levels. Fight against intense computer AI in the single player missions or wage war against 7 other aspiring “Aces” online.' FROM games WHERE igdb_id = 21266 ON CONFLICT (game_id, language_code) DO NOTHING;
