INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Empire: Immortals', 'Lost Empire: Immortals is a 4x turn-based strategy game, featuring multiple star maps with up to 5000 star systems, 6 different races and an extensive research tree. The battles are rendered in 3D - although the player cannot control them - and the final objectives can be domination, diplomacy, research or exploration.' FROM games WHERE igdb_id = 21470 ON CONFLICT (game_id, language_code) DO NOTHING;
