INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jumper: Griffin''s Story', 'Jump through an infinite world where there are no boundaries. You are Griffin, a teenage anti-hero, who can teleport through a rift between the time/space continuum. Jump the planet to hunt down packs of Paladins, an evil group of super-humans responsible for killing Griffin''s family and altering his world forever. Combat and teleport your way through visually stimulating levels of time and space to conquer Griffin''s enemies in this action-packed crusade.' FROM games WHERE igdb_id = 4944 ON CONFLICT (game_id, language_code) DO NOTHING;
