INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glory of Heracles', 'Glory of Heracles features the eponymous Greek hero in a pick-up-and-play role-playing game that has a rich storyline in a Greek motif and a deep battle system. The story begins when Heracles washes up on a beach with amnesia. Players must journey far and wide to figure out Heracles'' story and unravel the mysterious pasts of the other main characters in this new adventure. The game uses ancient Greece as its backdrop, and players can visit cities like Sparta and Athens on their travels.' FROM games WHERE igdb_id = 21766 ON CONFLICT (game_id, language_code) DO NOTHING;
