INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Band', 'Ultimate Band forgoes the use of specialized peripherals such as guitar and drum controllers, relying mainly on the Wii Remote and Nunchuk for the Wii version, and the touch screen and stylus for the DS version. For example, to play notes on guitar in the Wii version the player must press a button combination on the Nunchuk while strumming the Wii Remote up and down.' FROM games WHERE igdb_id = 5250 ON CONFLICT (game_id, language_code) DO NOTHING;
