INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon World Championship', 'It varies from other Digimon DS games in that the player does not give commands in a fight but the Digimon choose their attacks themselves. It also requires that the player feeds and looks after their Digimon, also having to heal, cure, and clean up after them, much like the older Digimon games. This is also the first Digimon game to include the Dracomon line of Digimon, featuring Petitmon, Babydmon, Dracomon, Coredramon (Air), Coredramon (Ground), Wingdramon, Groundramon, Slayerdramon, and Breakdramon. The starting Digimon is Botamon.' FROM games WHERE igdb_id = 47897 ON CONFLICT (game_id, language_code) DO NOTHING;
