INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Professor Kageyama''s Maths Training', 'Méthode Mathématique Du Professeur Kageyama sur DS vous fait réviser vos bases mathématiques afin que vous puissiez briller en société lors de la résolution d''une équation à inconnues multiples. Le titre s''appuie sur une méthode japonaise visant à apprendre l''arithmétique en faisant faire des opérations via un tableau rempli de chiffres qu''il faut compléter, à travers 20 niveaux de difficulté et 40 exercices proposés.' FROM games WHERE igdb_id = 21507 ON CONFLICT (game_id, language_code) DO NOTHING;
