INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speed Racer: The Videogame', 'In Speed Racer, players take on the role of the characters from the film, getting behind the wheels of each character''s signature vehicles to experience firsthand the film''s high adrenaline, combative racing style. Perform tricks and pull off insane stunts through incredible, twisting stadium tracks, all while fighting against rival racers with incredible Car-Fu action.' FROM games WHERE igdb_id = 5176 ON CONFLICT (game_id, language_code) DO NOTHING;
