INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hell''s Kitchen: The Game', 'Experience the thrill of Hell''s Kitchen as you prove yourself to Chef Ramsay. Each day is a new challenge as you work your way towards a 5-star chef, unlocking real recipes as you progress. Master service, preparation and cooking while Gordon Ramsay watches over you- yelling and praising based on your performance. Be careful - if he gets too frustrated, he''ll shut down the kitchen!' FROM games WHERE igdb_id = 21358 ON CONFLICT (game_id, language_code) DO NOTHING;
