INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amorphous+', 'Amorphous+ is a top-down view action game that has you playing as a generic bald human. You exterminate nests of creatures known as Glooples, using your trusty sword known as the "SplatMaster3000". The game is a sequel/update to the original Amorphous game, both developed by innocuousGames.' FROM games WHERE igdb_id = 8061 ON CONFLICT (game_id, language_code) DO NOTHING;
