INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr. Daisy Pet Vet', 'Dr. Daisy has just graduated from veterinary school and needs to complete 5 rotations to finish her residency. Help her diagnose and heal needy animals in this madcap dash classic. From the local veterinary clinic to a sea park all the way to a big city zoo, Daisy needs to keep her ailing friends happy and healthy. Upgrades are available at each location to showcase your style and speed-up your play. Grab your stethoscope and let''s get healin''!' FROM games WHERE igdb_id = 15790 ON CONFLICT (game_id, language_code) DO NOTHING;
