INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Bust-A-Move', 'The smash-hit classic arcade game is going where no bubble has gone before in Space Bust A Move! Help the twin brothers, Bub and Bob, as you journey to distant planets to collect "Cosmo Bubbles" in order to stop the evil Devilin from taking over the galaxy. With intense multiplayer competition, improved graphics, customization options, and mini-games, you''ve never busted bubbles like these!' FROM games WHERE igdb_id = 20484 ON CONFLICT (game_id, language_code) DO NOTHING;
