INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Sims 2: Apartment Pets', 'Your Sims are leaving the suburbs for the hustle and bustle of apartment life! They''re moving into a apartment building full of interesting neighbors and a wide variety of pets. Your Sim can adopt pets of their own to play with and care for. As the manager of the on-site pet spa, your Sim can earn Simoleons by making sure that the local pets get the right treatments to keep them-and their owners-happy. From loveable cats and dogs to all-new exotic animals including slithery snakes, colorful birds, and cuddly rabbits, your Sim will experience all the hilarious unpredictability of owning pets while enjoying their exciting new apartment lifestyle!' FROM games WHERE igdb_id = 21464 ON CONFLICT (game_id, language_code) DO NOTHING;
