INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Cycling Manager 2008', 'The 2008 edition features improved racing graphics, a new lighting system, more detailed backgrounds and incredibly realistic rider models and animations. The management aspect also offers more depth and realism due to the new tools and systems available. Plus, for the first time, you can now compete in professional track cycling.' FROM games WHERE igdb_id = 21940 ON CONFLICT (game_id, language_code) DO NOTHING;
