INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Let''s Tap', 'TAP INTO A WHOLE NEW WAY TO PLAY! Let’s TAP is a completely innovative gaming experience on Wii with easy to pick-up-and-play controls that will appeal to gamers of all ages. Simply place the Wii Remote on a box or a flat surface and tap! All methods of tapping (light, medium, hard) will allow you to jump hurdles and create environmental effects such as a dazzling fireworks display. All five fun-filled game modes can be played by up to four players: Tap Runner, Silent Blocks, Rhythm Tap, Bubble Voyager and Visualizer.' FROM games WHERE igdb_id = 4970 ON CONFLICT (game_id, language_code) DO NOTHING;
