INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shotest Shogi', 'Now that you understand why Japan is so fascinated with Shogi, upgrade to the full version of Shotest Shogi and try your hand at the intermediate and advanced tutorials, 16 different AI opponents with a wide range of skill levels, and multiplayer challenge. Make your way up the leaderboards, earn achievements, and develop your tactical skills in this magnificent strategy board game!' FROM games WHERE igdb_id = 21803 ON CONFLICT (game_id, language_code) DO NOTHING;
