INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Agatha Christie: Death on the Nile', 'Embark on a great Seek and Find adventure which brings a whole new way of enjoying the timeless Agatha Christie story of Death on the Nile! Assume the role of renowned detective Hercule Poirot, seeking clues to a mysterious murder aboard a ship, cruising the River Nile. Find hidden objects, clues and the hard evidence that you''ll need to question suspects and uncover the truth behind the Death on the Nile! Was it the obvious former fiance? Or the diamond thief? The answer may surprise you!' FROM games WHERE igdb_id = 21134 ON CONFLICT (game_id, language_code) DO NOTHING;
