INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar: ABBA', 'SingStar ABBA is a karaoke game featuring songs from the Swedish group ABBA. The group was active during the seventies, particularly in the disco/pop music. The game gives points which are distributed by the purity of singing, as in how well does one manage to stay on tune. It doesn''t matter if you change octaves in the middle of the song or what words are you singing in (it doesn''t have a word recognition), so your singing is rated by how well you manage to hit the correct note at the correct time.' FROM games WHERE igdb_id = 3306 ON CONFLICT (game_id, language_code) DO NOTHING;
