INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nitrobike', 'Ubisoft introduces Nitrobike, the only game on the Wii home video game system from Nintendo that lets you feel the reckless intensity of racing a nitro-charged dirt bike. Developed by Left Field Productions - makers of the Nintendo 64 classic Excitebike 64 - Nitrobike will bring motocross racing to the Wii for the very first time. Give yourself a nitrous boost to rocket past your opponents toward the finish line.' FROM games WHERE igdb_id = 5078 ON CONFLICT (game_id, language_code) DO NOTHING;
