INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocketmen: Axis of Evil', 'Rocketmen: Axis of Evil is a downloadable top-down shooter developed by A.C.R.O.N.Y.M. Games, Eyerisk Studios and published by Capcom for the PlayStation 3 and Xbox 360. The game is based on the constructible strategy game called Rocketmen from WizKids. It supports 1-4 person cooperative play either online or offline.' FROM games WHERE igdb_id = 20273 ON CONFLICT (game_id, language_code) DO NOTHING;
