INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Wizard of Oz: Beyond the Yellow Brick Road', 'The Wizard of Oz: Beyond the Yellow Brick Road, known in Japan as RIZ-ZOAWD, is a role-playing video game developed by Media.Vision for the Nintendo DS. The game is an adaptation of L. Frank Baum''s 1900 novel The Wonderful Wizard of Oz, using its characters, locations and plot. The game was originally published in Japan by D3 Publisher on December 25, 2008. Xseed Games published the game in North America on September 29, 2009.' FROM games WHERE igdb_id = 21116 ON CONFLICT (game_id, language_code) DO NOTHING;
