INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Littlest Pet Shop: Winter', 'Littlest Pet Shop: Winter is a virtual pet game where players collect and customize 20 different pets across four themed environments. Players earn Kibble Coins through 16 mini-games to unlock new pets, accessories, and playsets. The game features different pet categories including Fanciest, Cuddliest, Sportiest, and Chilliest, with over 100 accessories available for customization.' FROM games WHERE igdb_id = 47908 ON CONFLICT (game_id, language_code) DO NOTHING;
