INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NCAA Football 09', 'NCAA Football 09 is a college football video game created by EA Sports, a subsidiary of Electronic Arts. It is the successor to NCAA Football 08 in the NCAA Football series. The game was announced on February 14, 2008 and was released on July 15, 2008.[1][2] The Wii version of the game is titled NCAA Football 09 All-Play and launched under EA Sports'' new All-Play brand exclusive to the platform.[3]' FROM games WHERE igdb_id = 5065 ON CONFLICT (game_id, language_code) DO NOTHING;
