INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chaos Theory', 'Meet Chaos Theory! A balanced mix of arcade gameplay and challenging physics-based puzzle solving.The main objective in Chaos Theory is to fill "Collectors" with magnetically charged particles. Those particles move freely in the environment and are influenced by other objects and their magnetic forces. Attract free particles, bind them to objects, and shoot them onto the Collectors to finish a level.' FROM games WHERE igdb_id = 15945 ON CONFLICT (game_id, language_code) DO NOTHING;
