INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pirates: Duels on the High Seas', 'Set sail across the 7 seas! A chance encounter with an old sea dog, the legend of a fantastic treasure, - Thus begins an epic adventure for the 7 keys of the 7 seas - a daring battle against the Royal Navy, sea monsters, a Witch Queen and Blackbeard himself! 70 levels over 7 seas; collectable weapons, crew men and treasure. Jam packed with adventure - your crew await you captain! Choose a Pirates life - for gold and glory!' FROM games WHERE igdb_id = 21274 ON CONFLICT (game_id, language_code) DO NOTHING;
