INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Sims Carnival: Bumper Blast', 'From the creators of The Sims comes a shoot-em-up carnival game that will have you blasting away for hours! Shoot and tag sliding Sims bumpers but watch out for dangerous traps. Clear the bumpers before you run out of shots! Enjoy the game again and again as you master tough skill shots, score combos and bonuses, and shoot for a high score. More than 140 levels in two fun-filled game modes keep the arcade action coming!' FROM games WHERE igdb_id = 91768 ON CONFLICT (game_id, language_code) DO NOTHING;
