INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Settlers: Rise of an Empire - Gold Edition', 'In Settlers: Rise of an Empire Gold Edition, the player creates their own empire of bustling cities in a captivating medieval world. However, threats are always looming so you must be prepared to defend your mighty kingdom. Powered by RenderWare, everything is visible, highly detailed, and real.' FROM games WHERE igdb_id = 27830 ON CONFLICT (game_id, language_code) DO NOTHING;
