INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eternal Poison', 'Eternal Poison begins in the Kingdom of Valdia where the demonic realm of Besek has suddenly appeared. This realm is home to demons called the Majin who have captured Valdia''s Princess. The King of Valdia then issues a decree for her rescue which brings upon numerous adventurers of dissimilar intentions, the story of game is told from multiple perspectives of five key parties as they journey their way through the realm of Besek to rescue the princess.' FROM games WHERE igdb_id = 21334 ON CONFLICT (game_id, language_code) DO NOTHING;
