INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tak and the Guardians of Gross', 'While cleaning up a shrine, Tak removes a giant crystal and inadvertently releases the four Big G''s, four of the nastiest, most disgusting Titans to terrorize Tak''s village: Trashthulu the landfill giant, Slopviathan the slime giant, Gorgonzilla the molten cheese giant, and Stinkolossus the stink giant. Now Tak must find the Juju masters of the Big G''s and acquire the magic needed to stop the giants before they make a mess that will take Tak an eternity to clean up!' FROM games WHERE igdb_id = 2781 ON CONFLICT (game_id, language_code) DO NOTHING;
