INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Hill: Mobile 2', 'Silent Hill: Mobile 2 is the first sequel to Silent Hill: Orphan. The game features the same first-person, point-and-click gameplay as its prequel. Players are charged with using a clever point’n’click interface to solve a series of puzzles and combating hideous creatures, as a twisting plot gradually unfolds. As the game progresses, two parallel plots gradually entwine, and the player is drawn into a dark, macabre world brought to vivid life by the game’s visuals and eerie music and effects.' FROM games WHERE igdb_id = 134263 ON CONFLICT (game_id, language_code) DO NOTHING;
