INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VIP Casino Blackjack', 'The world''s most-played casino card game makes its WiiWare debut with highly detailed characters, true-to-life animations, and advanced artificial intelligence-making VIP Casino Blackjack the most realistic blackjack game ever made. This game broke the mold of traditional card games and their static 2D interface by integrating an animated 3D interface into the table, thus creating a visually impressive look and a play style that feels just right.' FROM games WHERE igdb_id = 21823 ON CONFLICT (game_id, language_code) DO NOTHING;
