INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scene It? Box Office Smash', 'Scene It? Box Office Smash brings movie and trivia fans together for a game that provides hours of laughter as you challenge your friends and family to see whose movie knowledge reigns supreme reliving some of your favorite moments from the silver screen. Continuing the franchise''s social and engaging trivia experience on the Xbox 360, Scene It? Box Office Smash features all-new questions, more high-definition (HD) movie clips and several new puzzle types, giving you a trivia game overflowing with images as well as audio and video clips from hundreds of films you know and love.' FROM games WHERE igdb_id = 7181 ON CONFLICT (game_id, language_code) DO NOTHING;
