INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imperium Romanum', 'The city builder strategy game Imperium Romanum is set in the time-honoured Roman Empire and players will marvel in the incredible attention to detail when working on a strategy to build a well organised, prosperous and commanding settlement. As governor of a Roman province, the fortune very much lies in the players own hands. Imperium Romanum is the sequel to Glory of the Roman Empire.' FROM games WHERE igdb_id = 20776 ON CONFLICT (game_id, language_code) DO NOTHING;
