INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zenses: Ocean', 'In Zenses Ocean, players relax themselves playing puzzle games inspired by the movements of the tide, rippling water, riffs and corals, beach vegetation and sea life. An indulgent, soothing experience, Zenses Ocean includes high quality visuals and ambient sounds inspired by the natural sounds of the sea.' FROM games WHERE igdb_id = 21138 ON CONFLICT (game_id, language_code) DO NOTHING;
