INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-wonderful-end-of-the-world', 14905, '2008-01-25', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co44l0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arqn2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Wonderful End of the World', 'You can''t save the whole world. It''s going to be eaten by a mythological demon with the head of a fish. But as a puppet that absorbs all it touches, you can try to rescue as much of Earth''s greatness as you can before the end arrives. In the beginning, you roam the Earth, capable of absorbing only the tiniest of objects. A glass marble you collect becomes your head, and a pair of jellybeans becomes your hands. Small creatures overwhelm you, with rats kicking you around and golden retrievers threatening to stomp you to pieces. But with every object you collect, your puppet self grows larger. Eventually, you''ll become a towering behemoth with fire engines for arms and the ability to absorb entire buildings. The Wonderful End of the World takes you through 12 unique locations, with over a thousand treasures to gather before the end comes. Steal some sweets from the candy store, where gummi fish swim in a blueberry river; visit a surrealist library to find that the words have literally leapt out of their books; and explore the Megalopolis, where you''ll watch a lively end-of-the-world parade and then gobble it up before making your way to grab the tallest skyscraper ever built.' FROM games WHERE igdb_id = 14905 ON CONFLICT (game_id, language_code) DO NOTHING;
