INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nanostray 2', 'Nanostray 2 is a sequel to the DS shoot-em-up Nanostray released in 2005. It features improvements over it''s prequel such as a new weapon system, enhanced touch controls, and unlockable minigames. It is developed by Shin''en Multimedia and published by Majesco.' FROM games WHERE igdb_id = 20992 ON CONFLICT (game_id, language_code) DO NOTHING;
