INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EA Sports Fantasy Football Live Draft Tracker', 'The Live Draft Tracker imports league and team information from the website, tracks the draft, and then uploads completed draft results back to the website saving the commish a lot of time and effort. Live Draft Tracker is packed with EA Expert analysis on the top players in the draft and highlight videos from Madden NFL 09.' FROM games WHERE igdb_id = 72895 ON CONFLICT (game_id, language_code) DO NOTHING;
