INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tales-of-symphonia-dawn-of-the-new-world', 5210, '2008-06-26', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5mt1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ak1x0cw3gekhzb9vpy9k.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Symphonia: Dawn of the New World', 'Set two years after the events of the award-winning Tales of Symphonia for the Nintendo GameCube, Dawn of the New World follows the journey of two new young heroes, Emil Castagnier and Marta Lualdi, as they seek to uncover the mystery of why their world has fallen into ruin. In their quest, their paths will cross with the original cast of Tales of Symphonia including Lloyd and Colette, as well as a summon spirit known as Ratatosk who claims to be the lord of all monsters. Advancing the combination of story, characters and real-time battles of Tales of Symphonia, Dawn of the New World introduces a new monster recruitment feature in which players can capture more than 200 unique enemies and train them to actively participate in battle. Players can then feed these monsters to make them more effective, and even evolve them into several new fearsome forms. The game also features an updated real-time battle system that lets players move freely in all directions around the battlefield, execute powerful unison attacks and take advantage of a new elemental alignment system for even more strategic depth. Dawn of the New World gives players complete control over a full roster of Tales of Symphonia characters and ally monsters, letting them customize their adventure party into hundreds of unique combinations.' FROM games WHERE igdb_id = 5210 ON CONFLICT (game_id, language_code) DO NOTHING;
