INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NFL Tour', 'NFL Tour is an arcade football video game. It was released on January 8, 2008. It was developed under the EA Sports BIG division of EA Sports, which is also responsible for such titles as SSX, NBA Street, NFL Street, and the FIFA Street games. The game could be considered a successor to the NFL Street franchise, but it was converted to the new hardware (PS3 / Xbox 360). Trey Wingo from ESPN is the game''s voice announcer.' FROM games WHERE igdb_id = 7118 ON CONFLICT (game_id, language_code) DO NOTHING;
