INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yamaha Supercross', 'You are the promising younger brother of one of the biggest names in Supercross. He was hospitalized in the final race of the World Championships in an obviously intentional move by the lead rider of Team Nemeshisu, the toughest team to beat and the dirtiest riders in the world of Supercross. You must work up through the championships by winning each race, to finally meet the man that injured your brother in the World Championships, and avenge him by becoming World Champion.' FROM games WHERE igdb_id = 5303 ON CONFLICT (game_id, language_code) DO NOTHING;
