INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('front-mission-2089-border-of-madness', 72662, '2008-05-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4hf6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1gcq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Front Mission 2089: Border of Madness', 'In fall 2007, Square Enix Co., Ltd. announced that it would be creating a remake of Front Mission 2089 on the Nintendo DS and named it Front Mission 2089: Border of Madness. The games producer Koichiro Sakamoto indicated that a survey of the series fans showed that most did not play games on their cell phones, and so Square Enix decided to bring it to the Nintendo DS. This remake of Front Mission 2089 featured completely remade visuals, new character artwork, new cut-scene events, a rewritten story, new game scenarios, and new battle maps. Also incorporated in the game were touchscreen features and a revised interface for more intuitive touchpad controls. Likewise, various game play mechanics from other Front Mission entries such as armor coating and linked attacks were added to Front Mission 2089: Border of Madness. Multiplayer mode had to be dropped due to space issues on the Nintendo DS.' FROM games WHERE igdb_id = 72662 ON CONFLICT (game_id, language_code) DO NOTHING;
