INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('viva-pinata-pocket-paradise', 21357, '2008-09-05', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mv6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lhkmnoopiyjvovz1kxty.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Viva Piñata: Pocket Paradise', 'In Viva Pinata: Pocket Paradise, players will inherit a neglected garden on Pinata Island and turn it into a pinata paradise by tending to all aspects of cleaning the garden, growing and maintaining vegetation, caring for and breeding pinatas, as well as attracting new pinata species. The game features seven all-new pinata species, each with new requirements, houses and unique cut scenes. Viva Pinata: Pocket Paradise also includes twelve full motion video clips that serve as tutorial levels within the game. The videos feature the stars of the Fox 4Kids Viva Pinata TV series, including Hudson Horstashio, Fergy Fudgehog and Paulie Pretztail. The brand-new Playground mode allows players to create a lush garden full of exciting and exotic pinatas in a very short amount of time. In addition, certain rare pinatas can only be acquired by using the Nintendo DS local wireless connection, where players can transfer items from their garden to a friend''s garden.' FROM games WHERE igdb_id = 21357 ON CONFLICT (game_id, language_code) DO NOTHING;
