INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shaun-white-snowboarding', 5152, '2008-11-14', 61, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coat9o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/y8wclcojrmislgb0h0yw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shaun White Snowboarding', 'Enter a snowboarding world of total freedom. You can create your own experience in this game, and choose when, where, how and with whom you want to ride. Developed in close collaboration with Olympic Gold Medalist Shaun White – the most successful snowboarder in the history of the sport – Shaun White Snowboarding is the next-gen game that redefines the action sports genre. Open-world mountains: Choose how you ride in open-world mountains accross the globe. Conquer the extreme peak conditions, create your own paths in the back country, or compete with fellow riders in the terrain park. Your friends are always around: Play in a world where your friends are always around. Do you own runs on mountains populated by real gamers, or join your friends for a quick session from anywhere in the mountains. More than just snowboarding: Have fun with your friends on and off the board: Throw snowballs, hike to access secret spots, film your friends doing crazy tricks. You can also upload your videos online to share with the world. Ride your way: Express yourself through tricks, riding styles, and highly customizable avatars both in single-player and in the online world. Use the intuitive dual analog control to pull off a huge variety of tricks that express your style.' FROM games WHERE igdb_id = 5152 ON CONFLICT (game_id, language_code) DO NOTHING;
