INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '100 Classic Book Collection', '100 Classic Book Collection turns your Nintendo DS into a portable library containing must-read novels from iconic authors such as Charles Dickens, Jane Austen, William Shakespeare, and many more. From Sense and Sensibility to Treasure Island, Moby Dick to A Midsummer Night''s Dream, Nintendo''s 100 Classic Book Collection presents 100 books that everyone should read--all conveniently housed in one single DS game cartridge. Hold the DS like a book and use the touch screen to turn the pages. 100 Classic Book Collection provides search methods to help you find a book that suits your mood and the amount of time you have to read.' FROM games WHERE igdb_id = 47939 ON CONFLICT (game_id, language_code) DO NOTHING;
