INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fable II: Pub Games', 'Unlock the full version of the Fable II Pub Games and you’ll get all three great pub games that will also be in Fable II! Each game has multiple variants, plus the ability to earn and transfer gold and unique items to your character in Fable II (assuming, of course, that you also have Fable II). Either way, you’ll also get access to minigames, leaderboards, achievements, and all the fun of these backroom games of chance!' FROM games WHERE igdb_id = 21328 ON CONFLICT (game_id, language_code) DO NOTHING;
