INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ragnarok DS', 'Ragnarok DS, known in Japan as Ragnarok Online DS, is a Nintendo DS video game based on the MMORPG Ragnarok Online and was released in Japan on December 18, 2008. It was announced that publisher Xseed Games had teamed up with developer GungHo Online Entertainment to bring the game to North America on February 16, 2010.' FROM games WHERE igdb_id = 21097 ON CONFLICT (game_id, language_code) DO NOTHING;
