INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle of Giants: Dinosaurs', 'Over 150 million years ago in a world dominated by Dinosaurs, natural disasters were changing earth and causing chaos. In the fight to become the top predator, only the most powerful dinosaurs could survive and had to battle the Arkosaurus, the most ferocious dinosaur species in the Jurassic world.' FROM games WHERE igdb_id = 7906 ON CONFLICT (game_id, language_code) DO NOTHING;
