INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Outcry', 'Outcry is a first person psychological thriller point-and-click adventure video game. You receive a letter from your brother, a scientist, who invites you to his home so that he can show you the results of his project, and you can get some ideas for your next book. However, once you arrive you find that your brother has mysteriously vanished, leaving all his material possessions to you - including a large, strange machine and a message telling you not to reproduce his experiments.' FROM games WHERE igdb_id = 13194 ON CONFLICT (game_id, language_code) DO NOTHING;
