INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('b-boy', 20565, '2008-08-05', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ogh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/h7gbwpjeszvkm3k0x0me.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'B-Boy', 'B-Boy allows you to battle through authentic Hip-Hop break-dancing culture, challenging the world''s best B-Boys on the world''s greatest B-Boy stages - and hopefully take home an in-game adidas sponsorship along the way. The first and only authentic break-dancing title on PSP stays true to the spirit of B-Boying thanks to the wireless functionality - giving you the freedom to battle on the move - anytime and anywhere - just as B-Boy competitions were meant to be. Featuring real life B-Boy characters, every in-game move is motion-captured from the experts, including moves taken from world famous Redbull athlete, "Crazy Legs", who also acts as game MC and end of level boss. Battling around the world, B-Boy features real locations and events, accompanied by the sound of a licensed Hip-Hop and classic Funk soundtrack with each track being selected by the B-Boys featured in-game. Progress through play by taking on 40 of the world''s greatest B-Boy personalities, and pull off unique moves and outrageous combo''s to become number one. Key game features include: 40 B-Boy characters to do battle with, including world famous B-Boy, Crazy Legs; 12 fully licensed motion-captured competitive B-Boys from Europe, Asia and North America; 21 authentic world wide locations including Redbull BC One, Freestyle Sessions, UK B-Boy Championships and IBE; 40 licensed Hip Hop and classic Funk tracks; Customise your B-Boy with full character personalisation - winning battles allows you to kit yourself out with the latest adidas clothing.' FROM games WHERE igdb_id = 20565 ON CONFLICT (game_id, language_code) DO NOTHING;
