INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('penny-arcade-adventures-on-the-rain-slick-precipice-of-darkness-episode-two', 14917, '2008-10-29', 78, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ink.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vtiewkour1esahleva8c.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Penny Arcade Adventures: On the Rain-Slick Precipice of Darkness - Episode Two', 'On the Rain-Slick Precipice of Darkness, Episode Two is the second installment in the RPG-adventure game series based on the web comic Penny Arcade. Whether you''re a fan of the first installment or new to the series, you''ll be able to pick up and play Episode Two as a standalone experience. Create your character in the classic comic style, and join Gabe and Tycho in the alternate 1920s universe of New Arcadia, where you''ll combat savage enemies, solve mysteries, meet bizarre new characters, and discover their distinctive adult humor for a 100% authentic Penny Arcade experience.' FROM games WHERE igdb_id = 14917 ON CONFLICT (game_id, language_code) DO NOTHING;
